style.css:
/* =========================================================
   ROBLOX YEAR 2000 FUTURE
   ULTRA FUTURISTIC EDITION
   ========================================================= */

:root {
    --bg: #02030a;
    --panel: rgba(8, 15, 30, .82);
    --line: #39d9ff;
    --blue: #168cff;
    --purple: #9b4dff;
    --cyan: #00f0ff;
    --text: #f5fbff;
}

/* ГЛАВНЫЙ ФОН */
html,
body {
    background:
        radial-gradient(circle at 50% 0%, #123d72 0%, transparent 35%),
        radial-gradient(circle at 10% 80%, #40136d 0%, transparent 30%),
        #02030a !important;

    color: var(--text) !important;

    font-family: Arial, Helvetica, sans-serif !important;
}

/* ФУТУРИСТИЧЕСКАЯ СЕТКА */
body {
    background-image:
        linear-gradient(rgba(40,180,255,.035) 1px, transparent 1px),
        linear-gradient(90deg, rgba(40,180,255,.035) 1px, transparent 1px) !important;

    background-size: 40px 40px !important;
}

/* ВЕРХНЯЯ ПАНЕЛЬ */
nav,
header,
[class*="navbar"],
[class*="header"] {
    background: rgba(2, 8, 20, .78) !important;

    border-bottom: 1px solid var(--line) !important;

    backdrop-filter: blur(25px) !important;

    box-shadow:
        0 0 25px rgba(0,220,255,.18),
        inset 0 -1px rgba(0,220,255,.5) !important;
}

/* ВСЕ ОСНОВНЫЕ ПАНЕЛИ */
[class*="card"],
[class*="panel"],
section,
[class*="container"] {
    background: var(--panel) !important;

    border: 1px solid rgba(57,217,255,.45) !important;

    border-radius: 20px !important;

    backdrop-filter: blur(25px) !important;

    box-shadow:
        0 0 25px rgba(0,180,255,.08),
        inset 0 0 25px rgba(50,120,255,.03) !important;

    transition:
        transform .25s,
        border-color .25s,
        box-shadow .25s !important;
}

/* ПАНЕЛИ ПРИ НАВЕДЕНИИ */
[class*="card"]:hover,
[class*="panel"]:hover {
    transform: translateY(-4px) scale(1.01) !important;

    border-color: var(--cyan) !important;

    box-shadow:
        0 0 35px rgba(0,220,255,.25),
        0 0 70px rgba(120,60,255,.12) !important;
}

/* СУПЕР-КНОПКИ */
button,
[class*="button"],
[class*="btn"] {
    background:
        linear-gradient(
            135deg,
            #087cff,
            #713dff,
            #00bfff
        ) !important;

    color: white !important;

    border: 1px solid #70eaff !important;

    border-radius: 12px !important;

    padding: 12px 26px !important;

    font-size: 16px !important;

    font-weight: 800 !important;

    letter-spacing: .4px !important;

    box-shadow:
        0 0 15px rgba(0,180,255,.35),
        inset 0 0 15px rgba(255,255,255,.08) !important;

    transition: .2s !important;
}

/* КНОПКА — НАВЕДЕНИЕ */
button:hover,
[class*="button"]:hover,
[class*="btn"]:hover {
    transform: translateY(-3px) scale(1.03) !important;

    filter: brightness(1.25) !important;

    box-shadow:
        0 0 25px rgba(0,220,255,.65),
        0 0 50px rgba(120,50,255,.35) !important;
}

/* КНОПКА — НАЖАТИЕ */
button:active,
[class*="button"]:active,
[class*="btn"]:active {
    transform: scale(.96) !important;
}

/* ПОЛЯ */
input,
textarea,
select {
    background: rgba(1, 8, 18, .9) !important;

    color: white !important;

    border: 1px solid #2d8dff !important;

    border-radius: 10px !important;

    padding: 11px !important;

    outline: none !important;
}

/* ПОЛЕ В ФОКУСЕ */
input:focus,
textarea:focus,
select:focus {
    border-color: var(--cyan) !important;

    box-shadow:
        0 0 15px rgba(0,230,255,.4) !important;
}

/* ЗАГОЛОВКИ */
h1,
h2,
h3 {
    color: white !important;

    font-weight: 900 !important;

    letter-spacing: -1px !important;

    text-shadow:
        0 0 10px rgba(0,220,255,.45),
        0 0 25px rgba(120,60,255,.25) !important;
}

h1 {
    font-size: 44px !important;
}

h2 {
    font-size: 34px !important;
}

h3 {
    font-size: 24px !important;
}

/* ССЫЛКИ */
a {
    color: #58dcff !important;

    transition: .2s !important;
}

a:hover {
    color: white !important;

    text-shadow:
        0 0 12px #00eaff !important;
}

/* АВАТАРЫ */
img {
    border-radius: 15px !important;
}

/* ОКНА */
[role="dialog"],
[role="menu"],
[class*="modal"],
[class*="dropdown"] {
    background: rgba(3, 10, 23, .94) !important;

    border: 1px solid #36dfff !important;

    border-radius: 18px !important;

    backdrop-filter: blur(30px) !important;

    box-shadow:
        0 0 40px rgba(0,220,255,.25),
        0 0 80px rgba(120,60,255,.15) !important;
}

/* СКРОЛЛБАР */
::-webkit-scrollbar {
    width: 10px !important;
}

::-webkit-scrollbar-track {
    background: #02050b !important;
}

::-webkit-scrollbar-thumb {
    background:
        linear-gradient(#00d9ff, #7b45ff) !important;

    border-radius: 10px !important;
}

/* УБИРАЕМ СТАРЫЕ ЭФФЕКТЫ */
* {
    text-shadow: none;
}

/* НО ОСТАВЛЯЕМ СВЕЧЕНИЕ ЗАГОЛОВКОВ */
h1,
h2,
h3 {
    text-shadow:
        0 0 10px #00d9ff,
        0 0 25px #743cff !important;
}
